// Layered debug checklist as runnable assertions (plain JS pattern)
const debugLayers = [
  ["transport", (ctx) => ctx.framingOk || "stdout polluted / connection dead"],
  ["discovery", (ctx) => ctx.discoverOk || "versions/capabilities mismatch"],
  ["validation", (ctx) => ctx.argsAccepted || "isError names the violated rule"],
  ["versions", (ctx) => ctx.mutual || "explicit version error, negotiate"],
  ["semantics", (ctx) => ctx.handlerOk || "logged inputs decide the fix"],
];
function diagnose(ctx) {
  for (const [layer, check] of debugLayers) {
    const res = check(ctx);
    if (res !== true) return { layer, finding: res };
  }
  return { layer: "none", finding: "all green — reproduce with minimal case" };
}
// First failing layer owns the incident; deeper layers wait their turn.

