function diagnose(ctx) {
  const layers = [
    ['transport', ctx.framingOk || 'stdout polluted'],
    ['discovery', ctx.discoverOk || 'version/capability mismatch'],
    ['validation', ctx.argsAccepted || 'isError names the rule'],
  ];
  for (const [layer, res] of layers) if (res !== true) return layer + ': ' + res;
  return 'all green';
}
console.log(diagnose({ framingOk: false }));
console.log(diagnose({ framingOk: true, discoverOk: false }));
console.log(diagnose({ framingOk: true, discoverOk: true, argsAccepted: false }));
console.log(diagnose({ framingOk: true, discoverOk: true, argsAccepted: true }));

